SELECT o.*, u.name AS user_name FROM oms_order o LEFT JOIN sys_user u ON u.id = o.user_id AND u.is_deleted = 0
o.is_deleted = 0
AND o.order_sn = #{orderSn}
AND u.name LIKE CONCAT('%', #{userName}, '%')
AND o.status IN
#{s}
AND o.create_time >= #{startTime}
AND o.create_time <= CONCAT(#{endTime}, ' 23:59:59')
ORDER BY o.create_time DESC
